reproduction_drivers.layout.py:
import pathlib,json,statistics,subprocess,os,sys,shutil,runpy
B=pathlib.Path('/data/mini_linq-wt/baseline-1106/target/baseline-1106')
rows=json.loads((B/'samples.json').read_text()); selected=[]
for name in sorted({r['kernel'] for r in rows if r.get('suite','').startswith('tpch-')}):
 for config in ['default','par']:
  s=[r for r in rows if r.get('suite')=='tpch-'+config and r.get('kernel')==name]
  ratio=statistics.median(r['value'] for r in s if r['side']=='current')/statistics.median(r['value'] for r in s if r['side']=='reference')
  if .95<=ratio<=1.05:selected.append((name,config))
(B/'layout-selection.json').write_text(json.dumps(selected))
if sys.argv[1]=='build':
 for name in sorted({n for n,c in selected}):
  crate=B/'reference/crates'/name
  env=dict(os.environ,CARGO_TARGET_DIR=str(B/'reference/target'))
  subprocess.run([str(B/'bin/cargo'),'rustc','--release','--locked','--offline','--manifest-path',str(crate/'Cargo.toml'),'--','-C','link-arg=-Wl,--shuffle-sections=*=42'],env=env,check=True)
  shutil.copy(B/'reference/target/release'/('tpch-derived-'+name),crate/'layout-worker')
else:
 sys.argv=[str(B/'measure.py'),'layout'];ns=runpy.run_path(str(B/'measure.py'))
 sample=ns['sample'];tmp=ns['TMP'];records=ns['records'];save=ns['save'];c=ns['c']
 for name,config in selected:
  for pair in range(5):
   for side in (['reference','shuffled'] if pair%2==0 else ['shuffled','reference']):
    label=f'layout-{name}-{config}-{pair}-{side}'
    if any(r['id']==label for r in records):continue
    metrics=tmp/'metrics.json';answers=tmp/'answers.json'
    cmd=[B/'reference/crates'/name/('timing-worker' if side=='reference' else 'layout-worker'),tmp/'data'/name,config,'3',answers,metrics,B/'current/raw'/name/'oracle.json']
    r=sample(cmd,label,{'BENCH_CHECK_MODE':'full' if pair==0 else 'sampled','BENCH_CHECK_SEED':str(20261106+pair),'RAYON_NUM_THREADS':'24'})
    m=json.loads(metrics.read_text());c.validation_evidence(m,require_native=True)
    r.update(id=label,suite='layout-'+config,kernel=name,config=config,pair=pair,side=side,value=m['median_ms'],metrics=m)
    records.append(r);save();answers.unlink();metrics.unlink();print(label,m['median_ms'],flush=True)

reproduction_drivers.fieldflow.py:
import pathlib,json,sys,runpy,os,subprocess,time,shutil
B=pathlib.Path('/data/mini_linq-wt/baseline-1106/target/baseline-1106');mode=sys.argv[1];sys.argv=[str(B/'measure.py'),'fieldflow'];ns=runpy.run_path(str(B/'measure.py'));sample=ns['sample'];T=ns['TMP'];Checker=ns['Checker']
F=B/'fieldflow-samples.json';records=json.loads(F.read_text()) if F.exists() else []
def save():F.write_text(json.dumps(records,indent=2))
def command(side,engine):
 return [B/side/'doop-target/release'/('srd-doop-mini' if engine=='mini' else 'srd-doop-mini-par'),'/data/doop-bench/doop-vs-srdatalog-20261026/fresh-corpus/prepared/xalan',*(['--threads','24'] if engine=='mini-par' else [])]
def counts(r):return json.loads(next(l.split('\t',1)[1] for l in r['stdout'].splitlines() if l.startswith('counts\t')))
if mode=='collect':
 if not any(r['id']=='fieldflow-export-oracle' for r in records):
  directory=T/'fieldflow-oracle';r=sample([*command('reference','mini'),'--export',directory],'fieldflow-export-oracle',{'RAYON_NUM_THREADS':'24'})
  r.update(id='fieldflow-export-oracle',purpose='oracle',exports=str(directory),relation_counts=counts(r));records.append(r);save()
 for engine in ['mini','mini-par']:
  for pair in range(5):
   for side in (['reference','current'] if pair%2==0 else ['current','reference']):
    label=f'fieldflow-export-{engine}-{side}-{pair}'
    if any(r['id']==label for r in records):continue
    env={'RAYON_NUM_THREADS':'24','BENCH_CHECK_MODE':'sampled','BENCH_CHECK_SEED':str(20261106+pair)}
    cmd=command(side,engine);directory=T/label
    if pair==0:cmd+=['--export',directory]
