import itertools,statistics,math,random

def percentile(v,p):
 v=sorted(v); k=(len(v)-1)*p; i=int(k); return v[i]+(v[min(i+1,len(v)-1)]-v[i])*(k-i)
def summarize(a,b):
 assert len(a)==len(b)==5
 draws=[statistics.median([a[i] for i in idx])/statistics.median([b[i] for i in idx]) for idx in itertools.product(range(5),repeat=5)]
 return {'current_median':statistics.median(a),'reference_median':statistics.median(b),'ratio':statistics.median(a)/statistics.median(b),'ci95':[percentile(draws,.025),percentile(draws,.975)],'current':a,'reference':b}
def suite(rows):
 rng=random.Random(20261106);draws=[]
 for _ in range(20000):
  ratios=[]
  for r in rows:
   idx=[rng.randrange(5) for _ in range(5)]
   ratios.append(statistics.median([r['current'][i] for i in idx])/statistics.median([r['reference'][i] for i in idx]))
  draws.append(math.exp(statistics.mean(map(math.log,ratios))))
 return {'ratio':math.exp(statistics.mean(math.log(r['ratio']) for r in rows)),'ci95':[percentile(draws,.025),percentile(draws,.975)]}
